head.script:
// 초기 렌더에 사용할 조건 기본값
//  con_ 셀렉트박스의 초기 선택 항목(빈 값 = 미설정)과 동일하게 맞춰 초기 표시값과 적용값이 어긋나지 않도록 한다.
//  Target 재생성 시 comp_init 이 con 선택값을 이 gVar 에 담아 동일한 경로로 사용한다.
scwin.gVar = {
    "cNextTabIDTarget" : "",
    "cNextTabIDInput" : "",
    "cNextTabIDButton" : "",
    "cNextTabIDSelectBox" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > nextTabID]<br/>Tab 키로 포커스 이동 시 마지막 Body Cell 에서 포커스가 이동될 다음 컴포넌트의 ID 를 설정합니다.",
    "validation" : [
        "포커스가 이동될 컴포넌트의 ID 를 문자열로 설정할 수 있어야 합니다.",
        "존재하지 않는 ID 설정 시 적용되지 않아야 합니다.",
        "다른 Scope 의 컴포넌트는 nextTabID 로 설정할 수 없어야 합니다.",
        "값을 설정하지 않으면 마지막 Body Cell 에서 일반적인 tabIndex 규칙을 따라야 합니다.",
        "포커스가 GridView 에 로드된 마지막 Row 의 마지막 Cell 에 위치한 상태에서 Tab 키 입력 시 nextTabID 속성이 동작해야 합니다.",
        "tabIndex 속성에 의한 순서는 무시되고 nextTabID 에 설정된 컴포넌트로 포커스가 이동되어야 합니다.",
        "nextTabID 대상이 포커스 불가 상태(disabled 등)이고 해당 대상에 nextTabID 가 설정되어 있으면 다음 컴포넌트로 포커스가 이동되어야 합니다.",
        "nextTabID 대상이 포커스 불가 상태(disabled 등)이고 해당 대상에 nextTabID 가 설정되어 있지 않으면 tabIndex 속성과 관계없이 포커스가 이동하지 않아야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdl_boolean 등)
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  nextTabID 는 렌더 시 결정되는 속성이므로 con 변경 후 Target 재생성으로만 반영한다.
//
//  [생성 순서] 기존 nextTabID 샘플과 동일한 구성(startcomp / input2 / button2 / selectbox2 / target1) 이며,
//   nextTabID 대상 컴포넌트가 대상을 지정하는 컴포넌트보다 먼저 생성되어야 매칭되므로
//   startcomp -> selectbox2 -> button2 -> input2 -> target1 순으로 생성한다.
//
//  [tabIndex] nextTabID 미적용 시의 자연스러운 Tab 이동 순서가
//   startcomp(1) -> target1(2) -> selectbox2(3) -> button2(4) -> input2(5) 가 되도록 부여한다.
//   · startcomp  : 초기 포커스 진입용 (tabIndex=1)
//   · target1    : 검증 대상 GridView (tabIndex=2)
//   · selectbox2 : tabIndex=3 / button2 : tabIndex=4 / input2 : tabIndex=5 (nextTabID 대상 후보)
//   → target1 의 자연 순서상 다음은 selectbox2 이므로, nextTabID 로 input2(자연 순서상 마지막)를 지정하면
//     tabIndex 순서가 무시되고 nextTabID 대상으로 이동하는지 확인할 수 있다.
scwin.comp_init = async function () {
    // 엔진의 nextTabID 매핑 저장소(WebSquare.tabOrder) 는 컴포넌트 remove 시 정리되지 않으므로
    //  Target 재생성 전에 이전 렌더의 매핑을 제거해야 변경한 con 값이 그대로 반영된다.
    let arrOldID = [];
    if (typeof target1 !== 'undefined') arrOldID.push(target1.id);
    if (typeof input2 !== 'undefined') arrOldID.push(input2.id);
    if (typeof button2 !== 'undefined') arrOldID.push(button2.id);
    if (typeof selectbox2 !== 'undefined') arrOldID.push(selectbox2.id);
    arrOldID.forEach(function (cid) {
        delete WebSquare.tabOrder[cid];
    });

    // 기존 target / dataList / 보조 컴포넌트 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof input2 !== 'undefined') {
        input2.remove();
    }
    if (typeof button2 !== 'undefined') {
        button2.remove();
    }
    if (typeof selectbox2 !== 'undefined') {
        selectbox2.remove();
    }
    if (typeof startcomp !== 'undefined') {
        startcomp.remove();
    }

    // con 선택값을 gVar 에 담는다 (dataList 바인딩 select1 -> getText(), 정적 select1 -> getValue())
    //  초기 로드 시 con 은 모두 빈 값이 선택되어 있어 gVar 선언부의 기본값과 동일하다.
    scwin.gVar["cNextTabIDTarget"] = con_nextTabID_target.getText();
    scwin.gVar["cNextTabIDInput"] = con_nextTabID_input.getText();
    scwin.gVar["cNextTabIDButton"] = con_nextTabID_button.getText();
    scwin.gVar["cNextTabIDSelectBox"] = con_nextTabID_selectbox.getText();

    let cNextTabIDTarget = scwin.gVar["cNextTabIDTarget"];
    let cNextTabIDInput = scwin.gVar["cNextTabIDInput"];
    let cNextTabIDButton = scwin.gVar["cNextTabIDButton"];
    let cNextTabIDSelectBox = scwin.gVar["cNextTabIDSelectBox"];

    // 테스트 참고 라벨 (가장 먼저 생성)
    let lbl = '';
    lbl += '[전제] tabIndex 순서 startcomp(1) -> target1(2) -> selectbox2(3) -> button2(4) -> input2(5). 생성 순서는 startcomp -> selectbox2 -> button2 -> input2 -> target1 이며, nextTabID 는 자신보다 먼저 생성된 컴포넌트를 지정해야 매칭됩니다.\n';
    lbl += '현재 설정 -> nextTabID(target)=' + (cNextTabIDTarget === '' ? '(미설정)' : cNextTabIDTarget)
        + ', nextTabID(input)=' + (cNextTabIDInput === '' ? '(미설정)' : cNextTabIDInput)
        + ', nextTabID(button)=' + (cNextTabIDButton === '' ? '(미설정)' : cNextTabIDButton)
        + ', nextTabID(selectbox)=' + (cNextTabIDSelectBox === '' ? '(미설정)' : cNextTabIDSelectBox) + '\n';
    lbl += '[절차] (1) GridView 의 마지막 Row 마지막 Cell(4번째 행 name4 컬럼)을 클릭해 셀에 포커스를 둔다 -> (2) Tab 키 입력. con 값을 바꾼 경우 먼저 Target 재생성을 눌러야 반영됩니다.\n';
    lbl += '[주의] 셀이 아닌 그리드 본체에 포커스가 있는 상태에서 Tab 을 누르면 nextTabID 가 적용되지 않고 tabIndex 순서(selectbox2)로 이동합니다. 결과창에 target1_onfocus (그리드 본체) 만 찍힌 뒤 Tab 을 누른 경우가 이에 해당하며, 셀 포커스 시에는 target1_oncellclick 이 출력됩니다.\n';
    lbl += 'nextTabID(target) 의 notExistId 는 존재하지 않는 ID, tbx_return 은 리턴 값 확인 wframe 에 있는 다른 Scope 의 컴포넌트입니다.\n';
    lbl += '포커스 불가 상태 검증은 setDisabled 버튼으로 대상 컴포넌트를 disabled 로 만든 뒤 Tab 키를 입력합니다.\n';
    lbl += '[확인] 포커스를 받은 컴포넌트의 onfocus 명이 하단 결과창에 출력됩니다. 출력이 없으면 포커스가 이동하지 않은 것입니다.';
    $c.gcm.createLabel('label="' + lbl + '"', '', 'label1');

    // 조건 설정 (target)
    //  focusMode="cell" 고정 : 마지막 Body Cell 에 포커스를 두고 Tab 키 동작을 확인하기 위함
    let properties = {
        tabIndex: 2,
        nextTabID: scwin.gVar["cNextTabIDTarget"],
        dataList: "data:dlt_bind",
        focusMode: "cell",
    };

    let cList = $c.gcm.createCList(properties);

    // 조건 설정 (input)
    let properties_input = {
        tabIndex: 5,
        nextTabID: scwin.gVar["cNextTabIDInput"],
    };

    let cList_input = $c.gcm.createCList(properties_input);

    // 조건 설정 (button)
    let properties_button = {
        tabIndex: 4,
        nextTabID: scwin.gVar["cNextTabIDButton"],
    };

    let cList_button = $c.gcm.createCList(properties_button);

    // 조건 설정 (selectbox)
    let properties_selectbox = {
        tabIndex: 3,
        nextTabID: scwin.gVar["cNextTabIDSelectBox"],
    };

    let cList_selectbox = $c.gcm.createCList(properties_selectbox);

    let grp_comp = $c.gcm.getTestGroup();

    let strNameSpace = $c.gcm.getNameSpace();
    let strStartComp = '';

    strStartComp += '<xf:input ' + strNameSpace + ' tabIndex="1" initValue="start" style="width:144px; height:21px;"></xf:input>';

    scwin.startcomp = await $p.dynamicCreate(
        "startcomp",
        "input",
        strStartComp,
        grp_comp
    );

    // GridView 바인딩용 dataList (4컬럼 4행)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    //  nextTabID 는 대상 컴포넌트가 먼저 생성되어 있어야 매칭되므로 selectbox2 -> button2 -> input2 -> target1 순으로 생성한다.
    await $c.gcm.createBasicSelectBox(cList_selectbox, 'ev:onfocus="scwin.selectbox2_onfocus"', "selectbox2");
    await $c.gcm.createBasicButton(cList_button, 'ev:onfocus="scwin.button2_onfocus"', "button2");
    await $c.gcm.createBasicInput(cList_input, 'ev:onfocus="scwin.input2_onfocus"', "input2");
    await $c.gcm.createBasicGridView(cList, 'ev:onfocus="scwin.target1_onfocus" ev:oncellclick="scwin.target1_oncellclick"');

    input2.setValue("input");
}



// 초기 포커스 이동
scwin.btn_setStartFocus_onclick = function (e) {
    startcomp.focus();
};



// nextTabID 대상을 포커스 불가 상태(disabled) 로 만든다
scwin.btn_setDisabled_onclick = function (e) {
    let cID = par_disabled.getText();
    let comp = (cID === 'input2') ? input2 : (cID === 'button2') ? button2 : selectbox2;
    comp.setDisabled(true);
};



// 포커스 이동 결과 확인
//  target1_onfocus 는 셀이 아닌 그리드 본체가 포커스를 받은 경우이며 이 상태에서 Tab 을 누르면 nextTabID 가 적용되지 않는다.
scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1_onfocus");
}



// nextTabID 동작 전제(마지막 Row 마지막 Cell 포커스) 확인용 - 현재 포커스된 셀 위치 출력
scwin.target1_oncellclick = function (rowIndex, colIndex) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1_oncellclick : rowIndex=" + rowIndex + ", colIndex=" + colIndex);
}



scwin.input2_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("input2_onfocus");
}



scwin.button2_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("button2_onfocus");
}



scwin.selectbox2_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("selectbox2_onfocus");
}
